<script setup lang="ts">
import {ref,watch} from 'vue'
import {service} from '@/services/service'
import {ElMessageBox} from 'element-plus'
import {ruleUsesField} from '@/domain/configuration'
import {createId} from '@/domain/ids'
import HardRulesEditor from './HardRulesEditor.vue'
import EngineeringMappings from './EngineeringMappings.vue'
import type {ToolDraft,Material} from '@/domain/types'
const props=defineProps<{draft:ToolDraft}>()
const columns=ref<Record<string,string[]>>({}),errors=ref<Record<string,string>>({}),loading=ref<Record<string,boolean>>({})
const roles=[{key:'name',label:'项目名称'},{key:'investment',label:'投资金额'},{key:'location',label:'建设地点'},{key:'content',label:'建设内容'},{key:'unit',label:'建设单位'}]
watch(()=>props.draft.tool==='association'?[props.draft.config.table1,props.draft.config.table2].filter(Boolean):props.draft.files,async files=>{
 for(const file of files as Material[]){if(props.draft.tool==='engineering')props.draft.config.fieldMappings[file.id] ||= {};if(columns.value[file.id]||loading.value[file.id])continue;loading.value[file.id]=true;try{const content=await service.getSource(file);columns.value[file.id]=content.columns||[];if(!content.columns?.length)errors.value[file.id]='未返回可用列名，请检查台账表头或解析结果。'}catch(e){errors.value[file.id]=(e as Error).message}finally{loading.value[file.id]=false}
 if(props.draft.tool==='engineering')props.draft.config.fieldMappings[file.id] ||= {}
 }
},{immediate:true,deep:false})
function addMapping(){const rows=(props.draft.config.mappingRows||=[]);const key='F'+(Math.max(0,...rows.map((r:any,i:number)=>Number((r.key||'F'+(i+1)).slice(1))))+1);rows.push({id:createId(),key,left:'',right:'',weight:rows.length?0:1,rule:'',compare_type:'similarity',threshold:0.8})}
async function removeMapping(i:number){const c=props.draft.config,key=c.mappingRows[i].key||'F'+(i+1),affected=c.hardRules.filter((r:any)=>ruleUsesField(r,key));if(affected.length){try{await ElMessageBox.confirm('移除这组字段对应时，将同时移除引用它的 '+affected.length+' 条判断规则。','移除字段对应',{confirmButtonText:'移除',cancelButtonText:'取消'})}catch{return}}c.hardRules=c.hardRules.filter((r:any)=>!ruleUsesField(r,key));c.mappingRows.splice(i,1)}
</script>
<template>
 <section class="form-section" v-if="draft.tool==='engineering'"><h3>检查内容</h3><el-checkbox v-model="draft.config.duplicateEnabled">重复项目识别</el-checkbox><el-checkbox v-model="draft.config.parentChildEnabled">主子项目识别</el-checkbox><p class="help">分别在每份台账内比较，不混合不同台账的记录。</p></section>
 <EngineeringMappings v-if="draft.tool==='engineering'" :draft="draft" :columns="columns" :errors="errors" :loading="loading"/><section v-else class="form-section"><h3>设置字段对应关系</h3>
  <p class="help">将表 A 与表 B 中含义相同的列对应起来。</p><div class="mapping-error" v-for="(error,id) in errors" :key="id">{{error}}</div><div class="pair-row" v-for="(row,i) in draft.config.mappingRows||[]" :key="row.id"><el-select v-model="row.left" filterable placeholder="表 A 字段" :aria-label="'表A字段 '+(Number(i)+1)"><el-option v-for="c in columns[draft.config.table1?.id]" :key="c" :value="c"/></el-select><span>↔</span><el-select v-model="row.right" filterable placeholder="表 B 字段" :aria-label="'表B字段 '+(Number(i)+1)"><el-option v-for="c in columns[draft.config.table2?.id]" :key="c" :value="c"/></el-select><button class="icon-button" aria-label="移除字段对应" @click="removeMapping(Number(i))">×</button></div><el-button @click="addMapping" :disabled="!draft.config.table1||!draft.config.table2">添加字段对应</el-button>
 </section>
 <section class="form-section"><h3>匹配判断</h3><div class="threshold-grid" v-if="draft.tool==='engineering'"><label v-if="draft.config.duplicateEnabled">重复项目阈值（0–5 分）<el-input-number v-model="draft.config.duplicateThreshold" :min="0" :max="5" :step="0.05"/></label><label v-if="draft.config.parentChildEnabled">主子项目阈值（0–5 分）<el-input-number v-model="draft.config.parentChildThreshold" :min="0" :max="5" :step="0.05"/></label></div><div class="threshold-grid" v-else><label>完全匹配阈值（0–5 分）<el-input-number v-model="draft.config.fullMatchThreshold" :min="0" :max="5" :step="0.1"/></label><label>部分匹配阈值（0–5 分）<el-input-number v-model="draft.config.partialMatchThreshold" :min="0" :max="5" :step="0.1"/></label></div><p class="help">分数越高，匹配要求越严格；候选关系仍需核对原表。</p></section>
 <el-collapse><el-collapse-item title="字段评分与高级设置" name="advanced">
  <template v-if="draft.tool==='engineering'"><label class="field-label">候选筛选至少匹配字段数</label><el-input-number v-model="draft.config.minMatchFields" :min="1" :max="100" :step="1"/><p class="help">其余硬规则、否决规则和编码识别参数沿用对应提示词的设置。</p></template>
  <template v-else><p class="help">各字段权重合计应为 1，当前为 {{(draft.config.mappingRows||[]).reduce((sum:number,r:any)=>sum+Number(r.weight||0),0).toFixed(2)}}。</p><el-button @click="(draft.config.mappingRows||[]).forEach((r:any)=>r.weight=1/draft.config.mappingRows.length)">均分权重</el-button><div v-for="row in draft.config.mappingRows||[]" :key="row.id" class="weight-row"><label>{{row.left||'未选择字段'}}</label><el-input-number v-model="row.weight" :min="0" :max="1" :step="0.05"/><el-input v-model="row.rule" placeholder="比较规则"/><el-select v-model="row.compare_type" style="width:150px;flex-shrink:0" aria-label="比较方式"><el-option label="文本相似度" value="similarity"/><el-option label="金额差异" value="investment_diff"/><el-option label="完全相等" value="exact"/></el-select></div><label class="field-label">每行最大候选数</label><el-input-number v-model="draft.config.candidateLimit" :min="1" :max="100"/><label class="field-label">最大比较对数</label><el-input-number v-model="draft.config.maxTotalPairs" :min="1" :max="1000000"/><div><el-checkbox v-model="draft.config.matchLock">完全匹配后锁定对应记录</el-checkbox></div><HardRulesEditor v-model="draft.config.hardRules" :fields="(draft.config.mappingRows||[]).map((r:any,i:number)=>({key:r.key||'F'+(i+1),label:(r.left||'未设置')+' ↔ '+(r.right||'未设置')}))"/></template>
 </el-collapse-item></el-collapse>
</template>
<style scoped>.mapping-file{margin-bottom:18px}.mapping-file h4{margin:10px 0;font-size:14px}.mapping-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:10px}.mapping-grid label{display:grid;grid-template-columns:80px 1fr;gap:8px;align-items:center;font-size:14px}.mapping-error{color:#a33e3e;font-size:14px;margin:10px 0}.pair-row{display:flex;gap:8px;align-items:center;margin-bottom:10px}.pair-row .el-select{flex:1;min-width:0}.threshold-grid{display:flex;gap:24px;flex-wrap:wrap;font-size:14px}.threshold-grid label{display:flex;flex-direction:column;gap:8px}.weight-row{display:flex;gap:10px;align-items:center;margin:12px 0}.weight-row>label{width:100px;flex-shrink:0}.weight-row .el-input-number{width:130px;flex-shrink:0}@media(max-width:620px){.weight-row{flex-wrap:wrap}}</style>
